const fs=require('fs');
const FILES=['prepareBugCreationContext','checkBugToFixReady','developBugAndCreatePR','checkBugTestsPassed','notifyBugMerged'];
function parse(f){
  const rows=fs.readFileSync(f,'utf8').split('\n').map(l=>l.match(/^(.+?)\s{2,}(\S+\.js)\s{2,}(\d+)\s+([\d.]+|N\/A)\s+([\d.]+|N\/A)\s*$/)).filter(Boolean).map(m=>({name:m[1],file:m[2],crap:m[5]}));
  return rows;
}
for (const [label,f] of [['MAIN','/tmp/crap-main.txt'],['HEAD','/tmp/crap-head.txt']]) {
  const rows=parse(f);
  let max=null,over=0;
  for(const r of rows){ if(r.crap==='N/A')continue; const v=parseFloat(r.crap); if(!max||v>max.v)max={v,name:r.name,file:r.file}; if(v>8)over++; }
  console.log(label,'real-rows='+rows.length,'max='+max.v+' ('+max.name+' @ '+max.file+')','over8='+over);
  for (const n of FILES) {
    const fr=rows.filter(r=>r.file.endsWith('/js/'+n+'.js')&&r.crap!=='N/A'&&parseFloat(r.crap)>8);
    if (fr.length) console.log('  ',label,n+'.js >8:',fr.map(r=>r.name+'='+r.crap).join(', '));
  }
}"

