function collectDirectTcLinks(ticket, testCaseType) {
    const issueLinks = ticket && ticket.fields && ticket.fields.issuelinks;
    if (!Array.isArray(issueLinks) || issueLinks.length === 0) {
        return [];
    }
    const tcs = [];
    issueLinks.forEach(function(link) {
