        const blockingCount = blockingTCs.length;

        console.log('Blocking Test Cases:', blockingCount, '/', totalTCs);

        if (blockingCount > 0) {
            return resolveBlockingRoute(tracker, ticketKey, labels, totalTCs, blockingTCs, jiraConfig, removeLabel);
        }

