const fs=require('fs');
const FILES=['prepareBugCreationContext','checkBugToFixReady','developBugAndCreatePR','checkBugTestsPassed','notifyBugMerged'];
function parse(f){
  return fs.readFileSync(f,'utf8').split('\n')
    .map(l=>l.match(/^(.+?)\s{2,}(\S+\.js)\s{2,}(\d+)\s+([\d.]+|N\/A)%?\s+([\d.]+|N\/A)\s*$/))
    .filter(Boolean)
    .map(m=>({name:m[1],file:m[2],crap:m[5]}));
}
function diff(a,b){
  const A=parse(a),B=parse(b);
  const ma=new Map(A.map(r=>[r.file+'::'+r.name,r.crap]));
  console.log('-- new keys with CRAP>8:');
  let n=0;
  for(const r of B){ if(!ma.has(r.file+'::'+r.name)&&r.crap!=='N/A'&&parseFloat(r.crap)>8){console.log('   '+r.file+'::'+r.name+' = '+r.crap);n++;} }
  if(!n)console.log('   (none)');
  console.log('-- shared keys that grew > epsilon:');
